const crypto = require('crypto');
const input = $input.first().json;
const headers = input.headers ?? {};
const payload = input.body;
const timestamp = Number(headers['x-signature-timestamp']);
const eventId = headers['x-event-id'];
const requestId = headers['x-request-id'];
const signature = headers['x-signature'];
const now = Math.floor(Date.now() / 1000);
const rawBody = typeof input.rawBody === 'string' ? input.rawBody : JSON.stringify(payload);
const bodyHash = crypto.createHash('sha256').update(rawBody).digest('hex');
const canonical = ['v1', String(timestamp), eventId, requestId, 'POST', '/webhook/career-analysis', bodyHash].join('\n');
const expected = `v1=${crypto.createHmac('sha256', $env.WORKER_TO_N8N_SECRET).update(canonical).digest('hex')}`;
const signatureValid = typeof signature === 'string' && signature.length === expected.length && crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
const identifiersValid = payload?.eventId === eventId && payload?.requestId === requestId && payload?.kind === 'job_posting_collection' && payload?.schemaVersion === '1.0.0' && payload?.collectionRunId && payload?.jobPosting?.source === 'wanted' && payload?.callbackPath === `/v1/internal/job-posting-collections/${payload?.collectionRunId}/complete`;
const valid = Number.isInteger(timestamp) && Math.abs(now - timestamp) <= 300 && signatureValid && Boolean(identifiersValid);
return [{ json: { valid, payload: valid ? payload : null } }];

const payload = $('HMAC 요청 검증').first().json.payload;
const body = payload.jobPosting.manualContent;
const byteLength = Buffer.byteLength(body, 'utf8');
return [{ json: { callback: { schemaVersion: '1.0.0', eventId: payload.eventId, requestId: payload.requestId, collectionRunId: payload.collectionRunId, outcome: 'manual', occurredAt: new Date().toISOString(), response: { status: 200, contentType: 'text/plain; charset=utf-8', contentLength: byteLength, body } }, callbackPath: payload.callbackPath } }];

const payload = $('HMAC 요청 검증').first().json.payload;
const result = $input.first().json;
const errorText = String(result.error?.message ?? result.message ?? '');
const failed = Boolean(result.error) || !Number.isInteger(Number(result.statusCode));
if (failed) {
  const outcome = /timeout|timed out|aborted/i.test(errorText) ? 'timeout' : 'network_error';
  return [{ json: { callback: { schemaVersion: '1.0.0', eventId: payload.eventId, requestId: payload.requestId, collectionRunId: payload.collectionRunId, outcome, occurredAt: new Date().toISOString(), response: null }, callbackPath: payload.callbackPath } }];
}
const headers = result.headers ?? {};
const rawBody = typeof result.body === 'string' ? result.body : JSON.stringify(result.body ?? '');
const byteLength = Buffer.byteLength(rawBody, 'utf8');
const headerLength = Number(headers['content-length']);
return [{ json: { callback: { schemaVersion: '1.0.0', eventId: payload.eventId, requestId: payload.requestId, collectionRunId: payload.collectionRunId, outcome: 'response', occurredAt: new Date().toISOString(), response: { status: Number(result.statusCode), contentType: headers['content-type'] ?? null, contentLength: Number.isFinite(headerLength) ? headerLength : byteLength, body: byteLength > 600000 ? '' : rawBody } }, callbackPath: payload.callbackPath } }];

const crypto = require('crypto');
const item = $input.first().json;
const callback = item.callback;
const body = JSON.stringify(callback);
const timestamp = Math.floor(Date.now() / 1000);
const bodyHash = crypto.createHash('sha256').update(body).digest('hex');
const canonical = ['v1', String(timestamp), callback.eventId, callback.requestId, 'POST', item.callbackPath, bodyHash].join('\n');
const signature = `v1=${crypto.createHmac('sha256', $env.WORKER_CALLBACK_SECRET).update(canonical).digest('hex')}`;
const baseUrl = String($env.WORKER_CALLBACK_URL).replace(/\/$/, '');
const suffix = baseUrl.endsWith('/v1/internal') && item.callbackPath.startsWith('/v1/internal/') ? item.callbackPath.slice('/v1/internal'.length) : item.callbackPath;
const callbackUrl = `${baseUrl}${suffix}`;
return [{ json: { body, callbackUrl, headers: { eventId: callback.eventId, requestId: callback.requestId, signature, timestamp: String(timestamp) } } }];
